"""Раскадровка 2-го выпуска: сцены, привязанные к фразам итогового монтажа (edl.json → words с выходными временами).
Пишет remotion/src/ep2/data/ep2.json и shots.json (список сцен для «Монтажной»)."""
import json, re
E = json.load(open('edl.json'))
W = E['words']
norm = lambda s: re.sub(r'[^\w%]+', '', s.lower().replace('ё', 'е'))
T = [norm(w['w']) for w in W]

def at(phrase, after=0.0, end=False):
    toks = [norm(x) for x in phrase.split()]
    for i in range(len(W)):
        if W[i]['o'] < after: continue
        if all(i + j < len(W) and T[i + j].startswith(toks[j]) for j in range(len(toks))):
            return round(W[i + len(toks) - 1]['oe'] if end else W[i]['o'], 2)
    raise SystemExit(f'не нашла: {phrase} (после {after})')

I0 = E['intro_out']; IE = I0 + E['intro_len']
S = []  # сцены
def shot(title, plan, s, e, lay=None, bg=None, kind='collage', items=(), **kw):
    S.append(dict(title=title, plan=plan, kind=kind, s=round(s, 2), e=round(e, 2), lay=lay, bg=bg, items=list(items), **kw))
cut = lambda src, t, x, y, w, rot=0, e=None: dict(k='cut', src=src, t=t, x=x, y=y, w=w, rot=rot, **({'e': e} if e else {}))
lab = lambda text, t, x, y, size=54, rot=-3, bg=None, font='hand', e=None, tape=True: dict(k='label', text=text, t=t, x=x, y=y, size=size, rot=rot, bg=bg, font=font, tape=tape, **({'e': e} if e else {}))
ran = lambda text, t, x, y, size=110, rot=-2, e=None: dict(k='ransom', text=text, t=t, x=x, y=y, size=size, rot=rot, **({'e': e} if e else {}))
dig = lambda v, t, x, y, h=200, rot=-3, e=None: dict(k='digits', value=v, t=t, x=x, y=y, h=h, rot=rot, **({'e': e} if e else {}))
txt = lambda text, t, x, y, size=120, color='ink', font='u', rot=-2: dict(k='text', text=text, t=t, x=x, y=y, size=size, color=color, font=font, rot=rot)
strike = lambda t, x, y, w, rot=-4: dict(k='strike', t=t, x=x, y=y, w=w, rot=rot)
rows = lambda *r: [dict(text=a, t=b, **({'ck': c} if c else {})) for a, b, c in r]

